<?php
/** DeepSeek: the company and its open models, the app and DeepThink, privacy and data location, the OpenAI-compatible API. */

/** Mixture of Experts: a router sends each token to only two of eight experts; the active pair changes from token to token. Labels in one language. */
if (!function_exists('fig_deepseek_moe')) {
    function fig_deepseek_moe(string $lg): string
    {
        $t = $lg === 'it'
            ? ['Token', 'gatto', 'corre', 'Router', 'sceglie', 'Esperti', 'per ogni token', 'lavorano solo', '2 esperti su 8']
            : ['Token', 'cat', 'runs', 'Router', 'chooses', 'Experts', 'for each token', 'only 2 of the 8', 'experts do the work'];
        $rows = '';
        foreach (range(1, 8) as $i) { $y = 22 + ($i - 1) * 30; $rows .= '<rect x="330" y="' . $y . '" width="96" height="24" rx="8"/>'; }
        $names = '';
        foreach (range(1, 8) as $i) { $names .= '<text x="378" y="' . (39 + ($i - 1) * 30) . '">E' . $i . '</text>'; }
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 280" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52">
<style>.ga{animation:fa 8s infinite}.gb{animation:fb 8s infinite}@keyframes fa{0%,44%{opacity:1}50%,94%{opacity:0}100%{opacity:1}}@keyframes fb{0%,44%{opacity:0}50%,94%{opacity:1}100%{opacity:0}}@media (prefers-reduced-motion:reduce){.ga,.gb{animation:none}}</style>
<rect x="16" y="108" width="110" height="64" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/>
<text x="71" y="132" text-anchor="middle" font-size="13">{$t[0]}</text>
<text class="ga" x="71" y="156" text-anchor="middle" font-weight="700" font-size="17" fill="#1B66BC">{$t[1]}</text>
<text class="gb" opacity="0" x="71" y="156" text-anchor="middle" font-weight="700" font-size="17" fill="#1B66BC">{$t[2]}</text>
<path d="M126 140H156" stroke="#8A87B0" stroke-width="2"/>
<rect x="156" y="108" width="110" height="64" rx="12" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/>
<text x="211" y="136" text-anchor="middle" font-weight="700" fill="#5A36C9">{$t[3]}</text><text x="211" y="156" text-anchor="middle" font-size="13">{$t[4]}</text>
<g stroke="#E8590C" stroke-width="3" fill="none" stroke-linecap="round">
<g class="ga"><path d="M266 140C300 140 300 64 330 64"/><path d="M266 140C300 140 300 214 330 214"/></g>
<g class="gb" opacity="0"><path d="M266 140C300 140 300 124 330 124"/><path d="M266 140C300 140 300 244 330 244"/></g>
</g>
<g fill="#F1F0F8" stroke="#8A87B0" stroke-width="2">{$rows}</g>
<g fill="#FFE8D6" stroke="#E8590C" stroke-width="3"><g class="ga"><rect x="330" y="52" width="96" height="24" rx="8"/><rect x="330" y="202" width="96" height="24" rx="8"/></g><g class="gb" opacity="0"><rect x="330" y="112" width="96" height="24" rx="8"/><rect x="330" y="232" width="96" height="24" rx="8"/></g></g>
<g text-anchor="middle" font-weight="700" font-size="14">{$names}</g>
<text x="536" y="104" text-anchor="middle" font-weight="700">{$t[5]}</text>
<text x="536" y="134" text-anchor="middle" font-size="14">{$t[6]}</text><text x="536" y="154" text-anchor="middle" font-size="14">{$t[7]}</text><text x="536" y="174" text-anchor="middle" font-size="14">{$t[8]}</text>
</svg>
SVG;
    }
}

/** An OpenAI-compatible API: the same client code reaches different providers by changing the address, the key and the model name. Labels in one language. */
if (!function_exists('fig_deepseek_compat')) {
    function fig_deepseek_compat(string $lg): string
    {
        $t = $lg === 'it'
            ? ['Il tuo codice', 'stesso SDK openai,', 'stesse chiamate', 'cambiano solo', 'base_url, chiave, modello', 'altri fornitori compatibili', 'o un server locale']
            : ['Your code', 'same openai SDK,', 'same calls', 'only these change:', 'base_url, key, model', 'other compatible providers', 'or a local server'];
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 260" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52">
<defs><marker id="a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="#8A87B0"/></marker></defs>
<rect x="16" y="70" width="190" height="120" rx="14" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/>
<text x="111" y="104" text-anchor="middle" font-weight="700" fill="#1B66BC">{$t[0]}</text>
<text x="111" y="130" text-anchor="middle" font-size="13">{$t[1]}</text><text x="111" y="148" text-anchor="middle" font-size="13">{$t[2]}</text>
<g stroke="#8A87B0" stroke-width="2" fill="none" marker-end="url(#a)"><path d="M206 120C290 120 300 50 390 50"/><path d="M206 130H390"/><path d="M206 140C290 140 300 210 390 210"/></g>
<text x="111" y="216" text-anchor="middle" font-size="13">{$t[3]}</text><text x="111" y="236" text-anchor="middle" font-size="13" font-weight="700">{$t[4]}</text>
<g stroke-width="2"><rect x="394" y="22" width="232" height="56" rx="12" fill="#D5F6EA" stroke="#0B7F5C"/><rect x="394" y="102" width="232" height="56" rx="12" fill="#ECE6FF" stroke="#7048E8"/><rect x="394" y="182" width="232" height="56" rx="12" fill="#F1F0F8" stroke="#8A87B0" stroke-dasharray="6 4"/></g>
<g font-weight="700" font-size="14"><text x="410" y="55" fill="#0B7F5C">api.deepseek.com</text><text x="410" y="135" fill="#5A36C9">api.openai.com/v1</text></g>
<text x="410" y="205" font-size="13">{$t[5]}</text><text x="410" y="225" font-size="13">{$t[6]}</text>
</svg>
SVG;
    }
}

return [
    'id' => 'deepseek', 'family' => 'assistants', 'after' => null,
    'title' => L('DeepSeek', 'DeepSeek'), 'short' => L('DeepSeek', 'DeepSeek'), 'level' => L('Base', 'Basics'),
    'desc' => L('Il laboratorio cinese dei modelli aperti: da V3 e R1 a V4, l’app con DeepThink e ricerca, dove finiscono i dati, uso in locale e l’API compatibile con OpenAI.', 'The Chinese lab of open models: from V3 and R1 to V4, the app with DeepThink and search, where data ends up, local use and the OpenAI-compatible API.'),
    'lessons' => [
        lesson('intro', L('DeepSeek e i suoi modelli', 'DeepSeek and its models'), [
            P('**DeepSeek** è un’azienda cinese di ricerca sull’AI. A inizio 2025 il suo modello di ragionamento **DeepSeek-R1** ha fatto notizia in tutto il mondo: prestazioni vicine ai migliori modelli dell’epoca, pesi pubblicati con licenza **MIT** e costi di addestramento dichiarati molto più bassi del solito.', '**DeepSeek** is a Chinese AI research company. In early 2025 its reasoning model **DeepSeek-R1** made headlines worldwide: performance close to the best models of the time, weights published under the **MIT** licence and reported training costs far lower than usual.'),
            P('Le prime famiglie famose sono state **V3** (modello generalista) e **R1** (ragionamento). Dalla versione V3.1 le due cose si sono unite in un unico modello **ibrido**, che può rispondere subito o ragionare prima; nel 2026 è arrivata la generazione **V4**, in una versione più grande (Pro) e una più veloce (Flash). Usano un’architettura **Mixture of Experts**: il modello è enorme, ma per ogni token si attiva solo una parte degli “esperti”, il che rende l’inferenza più efficiente.', 'The first famous families were **V3** (general-purpose) and **R1** (reasoning). From version V3.1 the two merged into a single **hybrid** model that can answer straight away or reason first; in 2026 the **V4** generation arrived, in a larger version (Pro) and a faster one (Flash). They use a **Mixture of Experts** architecture: the model is huge, but only some of the “experts” activate for each token, making inference more efficient.'),
            Fig(L(fig_deepseek_moe('it'), fig_deepseek_moe('en')),
                L('Un token entra in un router, che lo manda solo a due degli otto esperti messi in colonna: gli esperti attivi sono evidenziati in arancione. Nell’animazione il token cambia e il router sceglie un’altra coppia.', 'A token goes into a router, which sends it to only two of the eight experts stacked in a column: the active experts are highlighted in orange. In the animation the token changes and the router picks another pair.'),
                L('Il modello è grande, ma per ogni token lavora solo una piccola parte.', 'The model is big, but only a small part of it works on each token.')),
        ], [
            Q('i1', L('Di quale paese è DeepSeek?', 'Which country is DeepSeek from?'), [L('Cina', 'China'), L('Francia', 'France'), L('Stati Uniti', 'United States'), L('Svizzera', 'Switzerland')], 0, L('Laboratorio di ricerca cinese.', 'Chinese research lab.')),
            Q('i2', L('Che cos’è DeepSeek-R1?', 'What is DeepSeek-R1?'), [L('Un modello di ragionamento a pesi aperti', 'An open-weight reasoning model'), L('Un telefono', 'A phone'), L('Un motore di ricerca', 'A search engine'), L('Un linguaggio di programmazione', 'A programming language')], 0, L('Con licenza MIT.', 'Under the MIT licence.')),
            Q('i3', L('Che cosa fa un’architettura Mixture of Experts?', 'What does a Mixture of Experts architecture do?'), [L('Attiva solo una parte del modello per ogni token', 'Activates only part of the model per token'), L('Usa esperti umani', 'Uses human experts'), L('Unisce più aziende', 'Merges several companies'), L('Raddoppia i costi', 'Doubles the costs')], 0, L('Più efficiente in inferenza.', 'More efficient at inference.')),
        ], task('text', L('Abbina ogni modello al suo scopo, uno per riga come `modello: scopo`. Modelli: `V3`, `R1`. Scopi: generalista, ragionamento.', 'Match each model to its purpose, one per line as `model: purpose`. Models: `V3`, `R1`. Purposes: general-purpose, reasoning.'), '', [re('V3\s*:\s*(generalista|general)', L('V3 è generalista', 'V3 is general-purpose')), re('R1\s*:\s*(ragionamento|reasoning)', L('R1 è per il ragionamento', 'R1 is for reasoning'))], '', "V3: generalista\nR1: ragionamento"), [
            dMatch(pMatch(), [['DeepSeek', L('Laboratorio cinese', 'Chinese lab')], ['V3', L('Modello generalista', 'General-purpose model')], ['R1', L('Modello di ragionamento', 'Reasoning model')], ['MIT', L('Licenza dei pesi', 'Weights licence')], ['Mixture of Experts', L('Solo alcuni esperti attivi', 'Only some experts active')]], L('DeepSeek in breve.', 'DeepSeek in short.')),
            dFlash(pFlash(), [[L('I pesi di DeepSeek-R1 sono stati pubblicati', 'DeepSeek-R1’s weights were published'), true], [L('DeepSeek è un’azienda francese', 'DeepSeek is a French company'), false], [L('In un MoE ogni token usa tutto il modello', 'In an MoE each token uses the whole model'), false], [L('R1 è un modello di ragionamento', 'R1 is a reasoning model'), true]], L('Modelli aperti, grande impatto.', 'Open models, big impact.')),
        ]),
        lesson('app', L('L’app e DeepThink', 'The app and DeepThink'), [
            P('L’assistente di DeepSeek si usa dal web e dalle app per telefono. Con **DeepThink** attivi il modello di ragionamento, che mostra i passaggi con cui arriva alla risposta: utile per matematica, logica e codice. Con la **ricerca** il modello consulta il web per informazioni recenti.', 'DeepSeek’s assistant is used from the web and phone apps. With **DeepThink** you turn on the reasoning model, which shows the steps it takes to reach the answer: useful for maths, logic and code. With **search** the model consults the web for recent information.'),
            P('Come con ogni modello, verifica i risultati importanti. Su alcuni argomenti politici e storici sensibili per la Cina, osservatori e utenti hanno notato risposte evasive o allineate alle posizioni ufficiali: tienine conto se usi l’app per questi temi.', 'As with any model, verify important results. On some political and historical topics sensitive in China, observers and users have noted evasive answers or ones aligned with official positions: keep that in mind if you use the app for such topics.'),
        ], [
            Q('a1', L('Che cosa attiva DeepThink?', 'What does DeepThink turn on?'), [L('Il modello di ragionamento', 'The reasoning model'), L('La modalità scura', 'Dark mode'), L('La traduzione automatica', 'Automatic translation'), L('Le notifiche', 'Notifications')], 0, L('Mostra i passaggi.', 'It shows the steps.')),
            Q('a2', L('Per quali compiti è utile il ragionamento?', 'Which tasks benefit from reasoning?'), [L('Matematica, logica e codice', 'Maths, logic and code'), L('Salutare', 'Greeting'), L('Scegliere un emoji', 'Choosing an emoji'), L('Nessuno', 'None')], 0, L('Problemi con più passaggi.', 'Multi-step problems.')),
            Q('a3', L('Che cosa è stato notato su alcuni temi politici sensibili?', 'What has been noted on some sensitive political topics?'), [L('Risposte evasive o allineate alle posizioni ufficiali', 'Evasive answers or ones aligned with official positions'), L('Risposte sempre più lunghe', 'Ever longer answers'), L('Nessuna differenza', 'No difference'), L('Errori di ortografia', 'Spelling mistakes')], 0, L('Meglio saperlo.', 'Better to know.')),
        ], task('text', L('Scrivi un problema da dare a DeepSeek con **DeepThink** attivo: un indovinello logico o di matematica, chiedendo di **mostrare i passaggi** e di dare la **risposta finale** a parte.', 'Write a problem for DeepSeek with **DeepThink** on: a logic or maths riddle, asking to **show the steps** and give the **final answer** separately.'), '', [re('passagg|step|ragiona|reason', L('Chiedi i passaggi', 'You ask for the steps')), re('risposta finale|final answer', L('Risposta finale a parte', 'Final answer separately')), re('\d', L('C’è un problema con dei numeri', 'There is a problem with numbers'))], '', 'Un treno parte alle 9:20 e viaggia per 2 ore e 55 minuti. A che ora arriva? Mostra i passaggi e poi scrivi la risposta finale su una riga a parte.'), [
            dMatch(pMatch(), [['DeepThink', L('Ragionamento visibile', 'Visible reasoning')], [L('Ricerca', 'Search'), L('Informazioni dal web', 'Information from the web')], [L('Verifica', 'Verification'), L('Controllare i risultati importanti', 'Checking important results')], [L('Temi sensibili', 'Sensitive topics'), L('Possibili risposte evasive', 'Possible evasive answers')]], L('Usare l’app con criterio.', 'Using the app wisely.')),
            dFlash(pFlash(), [[L('DeepThink mostra i passaggi del ragionamento', 'DeepThink shows the reasoning steps'), true], [L('Le risposte di DeepSeek non vanno mai verificate', 'DeepSeek answers never need checking'), false], [L('La ricerca web serve per informazioni recenti', 'Web search is for recent information'), true], [L('DeepSeek esiste solo da computer', 'DeepSeek only exists on computers'), false]], L('Ragionare, ma verificare.', 'Reason, but verify.')),
        ]),
        lesson('privacy', L('Privacy e dove vanno i dati', 'Privacy and where data goes'), [
            P('Secondo l’informativa sulla privacy di DeepSeek, i dati degli utenti dell’app e del servizio online sono conservati su **server nella Repubblica Popolare Cinese**. Per questo diverse autorità hanno chiesto chiarimenti: in Italia, a inizio 2025, il **Garante per la privacy** ha bloccato il trattamento dei dati degli utenti italiani da parte dell’app, che è sparita dagli store italiani, e altri paesi ne hanno vietato l’uso su dispositivi governativi. In seguito l’Antitrust italiana (AGCM) ha chiuso un’istruttoria dopo che DeepSeek si è impegnata ad avvisare in modo più chiaro del rischio di risposte inventate.', 'According to DeepSeek’s privacy policy, data from users of the app and online service is stored on **servers in the People’s Republic of China**. Several authorities therefore asked for clarification: in Italy, in early 2025, the **Garante per la privacy** (data protection authority) blocked the app’s processing of Italian users’ data, and the app disappeared from Italian app stores, while other countries banned its use on government devices. Later the Italian competition authority (AGCM) closed an investigation after DeepSeek committed to warning more clearly about the risk of made-up answers.'),
            P('C’è però un’alternativa: i pesi sono **aperti**, quindi i modelli DeepSeek si possono far girare **in locale** o presso un fornitore cloud di tua scelta, senza mandare dati ai server dell’azienda. Le versioni più piccole “distillate” girano anche su un buon computer.', 'There is an alternative, though: the weights are **open**, so DeepSeek models can run **locally** or with a cloud provider of your choice, without sending data to the company’s servers. The smaller “distilled” versions even run on a good computer.'),
        ], [
            Q('p1', L('Dove conserva i dati il servizio online di DeepSeek, secondo la sua informativa?', 'Where does DeepSeek’s online service store data, according to its policy?'), [L('Su server in Cina', 'On servers in China'), L('Solo sul tuo telefono', 'Only on your phone'), L('In Svizzera', 'In Switzerland'), L('Da nessuna parte', 'Nowhere')], 0, L('Lo dice l’informativa sulla privacy.', 'The privacy policy says so.')),
            Q('p2', L('Che cosa ha fatto il Garante italiano a inizio 2025?', 'What did the Italian Garante do in early 2025?'), [L('Ha bloccato il trattamento dei dati degli utenti italiani', 'Blocked the processing of Italian users’ data'), L('Ha premiato l’app', 'Awarded the app'), L('Niente', 'Nothing'), L('Ha comprato DeepSeek', 'Bought DeepSeek')], 0, L('Per dubbi sulla privacy.', 'Over privacy concerns.')),
            Q('p3', L('Come usare un modello DeepSeek senza inviare dati all’azienda?', 'How can you use a DeepSeek model without sending data to the company?'), [L('Farlo girare in locale con i pesi aperti', 'Run it locally with the open weights'), L('Usare l’app ufficiale', 'Use the official app'), L('Non si può', 'You cannot'), L('Scrivere in maiuscolo', 'Write in capitals')], 0, L('Per esempio con Ollama.', 'For example with Ollama.')),
        ], task('text', L('Scrivi due righe che inizino con `-`: un rischio dell’app online di DeepSeek per la privacy e un modo per evitarlo.', 'Write two lines starting with `-`: a privacy risk of DeepSeek’s online app and a way to avoid it.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due righe', 'Two lines')), re('Cina|China|server', L('Citi dove vanno i dati', 'You mention where data goes')), re('local|ollama|pesi|weights|propri[oa] server|own server', L('Proponi l’uso in locale', 'You suggest local use'))], '', "- i dati dell’app online sono conservati su server in Cina\n- far girare il modello in locale con i pesi aperti, per esempio con Ollama"), [
            dMatch(pMatch(), [[L('Informativa privacy', 'Privacy policy'), L('Dati su server in Cina', 'Data on servers in China')], [L('Garante italiano', 'Italian Garante'), L('Blocco a inizio 2025', 'Block in early 2025')], [L('Pesi aperti', 'Open weights'), L('Uso in locale possibile', 'Local use possible')], [L('Modelli distillati', 'Distilled models'), L('Versioni più piccole', 'Smaller versions')]], L('Conoscere i rischi e le alternative.', 'Knowing the risks and the alternatives.')),
            dFlash(pFlash(), [[L('I modelli DeepSeek si possono usare in locale', 'DeepSeek models can be used locally'), true], [L('L’app online conserva i dati solo sul telefono', 'The online app keeps data only on the phone'), false], [L('Alcuni paesi ne hanno limitato l’uso su dispositivi governativi', 'Some countries restricted its use on government devices'), true], [L('Usare i pesi in locale manda i dati in Cina', 'Using the weights locally sends data to China'), false]], L('Aperto non vuol dire online.', 'Open does not mean online.')),
        ]),
        lesson('api', L('L’API di DeepSeek', 'The DeepSeek API'), [
            P('L’API di DeepSeek è **compatibile con quella di OpenAI**: si usa lo stesso SDK `openai`, cambiando l’indirizzo (`base_url`) e la chiave. I vecchi nomi `deepseek-chat` e `deepseek-reasoner` sono stati ritirati: oggi si sceglie un modello della generazione attuale (per esempio `deepseek-v4-pro`) e si attiva il **ragionamento** con il parametro `thinking`.', 'DeepSeek’s API is **OpenAI-compatible**: you use the same `openai` SDK, changing the address (`base_url`) and the key. The old names `deepseek-chat` and `deepseek-reasoner` have been retired: today you pick a model of the current generation (for example `deepseek-v4-pro`) and turn on **reasoning** with the `thinking` parameter.'),
            Fig(L(fig_deepseek_compat('it'), fig_deepseek_compat('en')),
                L('A sinistra il riquadro del tuo codice, che usa lo stesso SDK openai; tre frecce portano a tre server diversi: api.deepseek.com, api.openai.com e altri fornitori compatibili o un server locale. Sotto le frecce: cambiano solo base_url, chiave e modello.', 'On the left, the box of your code, using the same openai SDK; three arrows lead to three different servers: api.deepseek.com, api.openai.com and other compatible providers or a local server. Under the arrows: only base_url, key and model change.'),
                L('Compatibile vuol dire che le chiamate restano uguali; i dati però vanno dove punta base_url.', 'Compatible means the calls stay the same; the data, though, goes wherever base_url points.')),
            C('import os
from openai import OpenAI

client = OpenAI(api_key=os.environ["DEEPSEEK_API_KEY"], base_url="https://api.deepseek.com")

risposta = client.chat.completions.create(
    model="deepseek-v4-pro",
    messages=[
        {"role": "system", "content": "Rispondi in italiano."},
        {"role": "user", "content": "Che cos’è una funzione ricorsiva?"},
    ],
    extra_body={"thinking": {"type": "enabled"}},   # ragiona prima di rispondere
)
print(risposta.choices[0].message.content)', 'python'),
            P('I nomi dei modelli cambiano con le nuove versioni: controlla la documentazione. L’API è nota per prezzi molto bassi. Valgono le stesse considerazioni sulla privacy dell’app: i dati inviati arrivano ai server dell’azienda. Per dati riservati preferisci l’uso in locale o un fornitore che ospita i modelli aperti nella giurisdizione che ti serve.', 'Model names change with new versions: check the documentation. The API is known for very low prices. The same privacy considerations as the app apply: data you send reaches the company’s servers. For confidential data prefer local use or a provider hosting the open models in the jurisdiction you need.'),
        ], [
            Q('d1', L('Quale SDK si può usare con l’API di DeepSeek?', 'Which SDK can be used with the DeepSeek API?'), [L('Quello di OpenAI, cambiando base_url', 'OpenAI’s, changing base_url'), L('Solo un SDK segreto', 'Only a secret SDK'), L('Nessuno', 'None'), L('Quello di Gmail', 'Gmail’s')], 0, L('API compatibile.', 'Compatible API.')),
            Q('d2', L('Come si chiede al modello di ragionare prima di rispondere?', 'How do you ask the model to reason before answering?'), [L('Con il parametro `thinking` abilitato', 'With the `thinking` parameter enabled'), L('Cambiando il `base_url`', 'By changing the `base_url`'), L('Scrivendo la domanda in maiuscolo', 'By writing the question in capitals'), L('Via API non si può', 'It cannot be done via API')], 0, L('I vecchi nomi `deepseek-reasoner` e `deepseek-chat` sono stati ritirati.', 'The old names `deepseek-reasoner` and `deepseek-chat` have been retired.')),
            Q('d3', L('Con dati riservati, che cosa conviene?', 'With confidential data, what is advisable?'), [L('Usare i modelli aperti in locale o presso un fornitore scelto', 'Using the open models locally or with a chosen provider'), L('Inviarli comunque all’API', 'Sending them to the API anyway'), L('Pubblicarli', 'Publishing them'), L('Niente', 'Nothing')], 0, L('Tu scegli dove vanno i dati.', 'You choose where the data goes.')),
        ], task('python', L('Crea il client `OpenAI` con la chiave da `os.environ["DEEPSEEK_API_KEY"]` e `base_url="https://api.deepseek.com"`, poi chiama `chat.completions.create` con un modello DeepSeek (per esempio `model="deepseek-v4-pro"`).', 'Create the `OpenAI` client with the key from `os.environ["DEEPSEEK_API_KEY"]` and `base_url="https://api.deepseek.com"`, then call `chat.completions.create` with a DeepSeek model (for example `model="deepseek-v4-pro"`).'), "import os\nfrom openai import OpenAI\n", [re('OpenAI\s*\(\s*api_key\s*=\s*os\.environ\s*\[\s*["\']DEEPSEEK_API_KEY["\']\s*\]\s*,\s*base_url\s*=\s*["\']https://api\.deepseek\.com["\']\s*\)', L('Il client punta a DeepSeek', 'The client points to DeepSeek')), re('chat\.completions\.create\s*\(', L('La chiamata', 'The call')), re('model\s*=\s*["\']deepseek-[\w.\-]+["\']', L('Un modello DeepSeek', 'A DeepSeek model'))], '', "client = OpenAI(api_key=os.environ[\"DEEPSEEK_API_KEY\"], base_url=\"https://api.deepseek.com\")\nr = client.chat.completions.create(model=\"deepseek-v4-pro\", messages=[{\"role\": \"user\", \"content\": \"Quanto fa 17 × 23?\"}])\nprint(r.choices[0].message.content)"), [
